from shipping import cost


def reference(weight, express, member):
    if weight <= 0:
        raise ValueError
    heavy = weight > 10
    if express:
        return (12.0 if heavy else 8.0) if member else (20.0 if heavy else 15.0)
    return 0.0 if member else (9.0 if heavy else 5.0)


for weight in (-1, 0, 0.5, 1, 10, 10.5, 50):
    for express in (False, True):
        for member in (False, True):
            try:
                want = reference(weight, express, member)
            except ValueError:
                try:
                    cost(weight, express, member)
                except ValueError:
                    continue
                raise AssertionError(f'cost({weight}, {express}, {member}) no longer raises ValueError')
            got = cost(weight, express, member)
            assert got == want, f'cost({weight}, {express}, {member}) is {got}, was {want}'

